#include <stdio.h>

#define MAX_VALUE 5

int main() {
    int a[] = {5, 1, 4, 1, 5, 2};
    int n = sizeof(a) / sizeof(a[0]);
    int counts[MAX_VALUE + 1] = {0};
    for (int i = 0; i < n; i++) {
        counts[a[i]]++;
    }
    int k = 0;
    for (int v = 0; v <= MAX_VALUE; v++) {
        while (counts[v]-- > 0) {
            a[k++] = v;
        }
    }
    for (int i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
